before.content:
$ErrorActionPreference = 'Stop'
$PSNativeCommandUseErrorActionPreference = $true
$root = Split-Path -Parent $PSScriptRoot
$repo = Join-Path $root 'build/stage1-repository'
$temp = Join-Path ([System.IO.Path]::GetTempPath()) ('ji-stage6-consumer-' + [guid]::NewGuid().ToString('N'))
New-Item -ItemType Directory -Path (Join-Path $temp 'src/main/java/fixture') -Force | Out-Null
try {
  & (Join-Path $root 'gradlew.bat') ':ji-bom:publishJavaPublicationToStage1Repository' ':ji-agent-api:publishJavaPublicationToStage1Repository' ':ji-agent-core:publishJavaPublicationToStage1Repository' ':ji-ai-api:publishJavaPublicationToStage1Repository' ':ji-session-api:publishJavaPublicationToStage1Repository' ':ji-session-memory:publishJavaPublicationToStage1Repository' ':ji-error-catalog:publishJavaPublicationToStage1Repository' --offline --no-daemon
  if ($LASTEXITCODE -ne 0) { throw "local publication failed: $LASTEXITCODE" }
  @"
pluginManagement { repositories { gradlePluginPortal(); mavenCentral() } }
dependencyResolutionManagement { repositories { maven { url = uri("$($repo.Replace('\','/'))") }; mavenCentral() } }

after.content:
'@ | Set-Content -Encoding utf8 (Join-Path $temp 'src/main/java/fixture/Consumer.java')
  & (Join-Path $root 'gradlew.bat') --offline --no-daemon -p $temp classes
  if ($LASTEXITCODE -ne 0) { throw "Gradle BOM consumer failed: $LASTEXITCODE" }
  foreach ($module in @('ji-bom','ji-agent-api')) {
    $moduleDirectory = Join-Path $repo "io/github/diodeme/ji/$module/0.1.0-SNAPSHOT"
    if (-not (Get-ChildItem $moduleDirectory -Filter '*.pom' | Select-Object -First 1)) { throw "$module POM is missing" }
  }
  foreach ($classifier in @('*-sources.jar','*-javadoc.jar')) {
    if (-not (Get-ChildItem (Join-Path $repo 'io/github/diodeme/ji/ji-agent-api/0.1.0-SNAPSHOT') -Filter $classifier | Select-Object -First 1)) {
      throw "ji-agent-api $classifier is missing"
    }
  }
  Write-Output 'STAGE6_GRADLE_BOM_CONSUMER_OK'

  $maven = Get-Command mvn -ErrorAction SilentlyContinue
  if ($maven) {
    $mavenTemp = Join-Path $temp 'maven'
    New-Item -ItemType Directory -Path (Join-Path $mavenTemp 'src/main/java/fixture') -Force | Out-Null
    Copy-Item (Join-Path $temp 'src/main/java/fixture/Consumer.java') (Join-Path $mavenTemp 'src/main/java/fixture/Consumer.java')
    @"
<project xmlns="http://maven.apache.org/POM/4.0.0"><modelVersion>4.0.0</modelVersion>
<groupId>fixture</groupId><artifactId>consumer</artifactId><version>1</version>
<properties><maven.compiler.release>21</maven.compiler.release></properties>
<repositories><repository><id>ji-stage6</id><url>$([Uri]::new($repo).AbsoluteUri)</url></repository></repositories>
<dependencyManagement><dependencies><dependency><groupId>io.github.diodeme.ji</groupId><artifactId>ji-bom</artifactId><version>0.1.0-SNAPSHOT</version><type>pom</type><scope>import</scope></dependency></dependencies></dependencyManagement>
<dependencies><dependency><groupId>io.github.diodeme.ji</groupId><artifactId>ji-agent-api</artifactId></dependency></dependencies>
</project>
"@ | Set-Content -Encoding utf8 (Join-Path $mavenTemp 'pom.xml')
    & $maven.Source -B -o -Dmaven.repo.local=(Join-Path $temp 'm2') -f (Join-Path $mavenTemp 'pom.xml') compile
    if ($LASTEXITCODE -ne 0) { throw "Maven BOM consumer failed: $LASTEXITCODE" }
    Write-Output 'STAGE6_MAVEN_CONSUMER_OK'
  } elseif ($RequireMaven) {
    throw 'Maven consumer is required but mvn is unavailable'
  } else {
    Write-Output 'STAGE6_MAVEN_CONSUMER_EXTERNAL_REQUIRED'
  }
} finally {
  Remove-Item -Recurse -Force $temp -ErrorAction SilentlyContinue
